    p=l.split(); S.append(p[0]); P.append([float(x) for x in p[1:4]])
P=np.array(P)
print('N:',n,'Formula:',''.join(f'{k}{v}' for k,v in sorted(Counter(S).items())))
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Cl':1.02,'Rh':1.42}
d=np.linalg.norm(P[:,None]-P[None],axis=2)
nb={i:[] for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        if d[i,j] < 1.25*(cov[S[i]]+cov[S[j]]):
            nb[i].append(j); nb[j].append(i)
for i in range(n):
    if S[i] in ('N','Rh','O','Cl'):
        print(i,S[i],'->',[(j,S[j],round(d[i,j],2)) for j in nb[i]])
dd=d.copy(); np.fill_diagonal(dd,9)
